let newmsg = {
    topic: "toggled",
    payload: 0
}

if ( msg.payload?true:false ){
    let state = context.get("toggle") || false;  // get previous state from the context, default false if none
    state = !state;                              // invert the state
    context.set("toggle", state);                // remember it by storing to the context
    newmsg.payload = state;
    return newmsg;
}

