if (msg.payload === 1 || msg.payload === true) {
    // If we are already running, don't start a duplicate timer
    if (context.get('running') === true) return null;
    let speed = 75;

    // Set running state to true
    context.set('running', true);
    context.set('currentValue', 1); // Start with 1

    // Define the loops function
    function toggle() {
        // If someone set running to false in the meantime, stop the loop
        if (context.get('running') !== true) return;

        // Get the current value and flip it (1 to 0, or 0 to 1)
        let val = context.get('currentValue');
        val = (val === 1) ? 0 : 1;
        context.set('currentValue', val);

        // Send out the flipped value
        node.send({ payload: val });

        // Run this function again after a set time
        let timer = setTimeout(toggle, speed);
        context.set('timerId', timer);
    }

    // Send out the very first '1' immediately
    msg.payload = 1;
    node.send(msg);

    // Start the looping sequence
    let timer = setTimeout(toggle, speed);
    context.set('timerId', timer);
    return null;
}

