// Initialize the message storage
context.set('lastMsg', null);

// Start the 1-second interval loop
const intervalId = setInterval(() => {
    const msgToRepeat = context.get('lastMsg');
    if (msgToRepeat) {
        // Safely clone and send the message downstream
        node.send(RED.util.cloneMessage(msgToRepeat));
    }
}, 1000); // 1000ms = 1 second

// Save the loop ID so we can clean it up later
context.set('intervalId', intervalId);

finalize:
// Stop the background loop on redeploy
const intervalId = context.get('intervalId');
if (intervalId) {
    clearInterval(intervalId);
    context.set('intervalId', null);
}

