// ONLY allow the code to run if the button is actively pressed.
// Adjust this if your button sends 1 on a press instead of 0.
if (msg.payload !== 0 && msg.payload !== false) {
    return null; // Stop the flow right here if it's a release or startup state
}

// Set a fixed frequency (800Hz is a standard alert beep)
const frequency = 1200;

// 2. Set duration of the bleep (0.15 seconds)
const duration = 0.15; 
const sampleRate = 8000;
const numSamples = Math.floor(sampleRate * duration);

// 3. Create the audio byte array
const audioData = new Uint8Array(numSamples);
for (let i = 0; i < numSamples; i++) {
    // Generate sine wave
    let t = i / sampleRate;
    let sample = Math.sin(2 * Math.PI * frequency * t);

    // Convert to an 8-bit unsigned integer (0 to 255)
    audioData[i] = Math.floor((sample + 1) * 127.5);
}

// 4. Build standard RIFF/WAV header strings
const header = new Uint8Array(44);
const view = new DataView(header.buffer);

function writeString(offset, string) {
    for (let i = 0; i < string.length; i++) {
        view.setUint8(offset + i, string.charCodeAt(i));
    }
}

writeString(0, 'RIFF');
view.setUint32(4, 36 + numSamples, true);
writeString(8, 'WAVE');
writeString(12, 'fmt ');
view.setUint32(16, 16, true);         // Subchunk1Size
view.setUint16(20, 1, true);          // AudioFormat (PCM)
view.setUint16(22, 1, true);          // NumChannels (Mono)
view.setUint32(24, sampleRate, true); // SampleRate
view.setUint32(28, sampleRate, true); // ByteRate
view.setUint16(32, 1, true);          // BlockAlign
view.setUint16(34, 8, true);          // BitsPerSample (8-bit)
writeString(36, 'data');
view.setUint32(40, numSamples, true);

// 5. Combine header and raw sound bytes into a single base64 data URL
const totalBuffer = new Uint8Array(header.length + audioData.length);
totalBuffer.set(header, 0);
totalBuffer.set(audioData, header.length);

const base64Data = Buffer.from(totalBuffer).toString('base64');
const dataUrl = "data:audio/wav;base64," + base64Data +"#" + Math.random();;

// 6. Send the data URL directly to the audio node payload
msg.payload = dataUrl;
msg.ui_update = { id: Date.now() }; 

return msg;

